KEYS = tuple(ROLES)

def display_options(index):
    order = KEYS[index % 4:] + KEYS[:index % 4]
    return [(key, QUESTIONS[index][2][KEYS.index(key)]) for key in order]

def score_answers(answers):
    if len(answers) != len(QUESTIONS) or any(a not in ROLES for a in answers):
        raise ValueError('12개의 문항에 모두 응답해야 합니다.')
    return {key: answers.count(key) for key in ROLES}

def result_groups(scores):
    highest = max(scores.values())
    winners = [k for k in KEYS if scores[k] == highest]
    lower = [scores[k] for k in KEYS if scores[k] < highest and scores[k] > 0]
    secondary = [k for k in KEYS if lower and scores[k] == max(lower)] if len(winners) == 1 else []
    return winners, secondary

